DROP TABLE IF EXISTS `bajas_concursos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bajas_concursos` (
  `id_baja` int NOT NULL,
  `id_cargo` int NOT NULL,
  `ex_baja` varchar(50) DEFAULT NULL,
  `sigla` varchar(20) DEFAULT NULL,
  `periodo` varchar(10) NOT NULL,
  `codigo_cargo` varchar(15) DEFAULT NULL,
  `ex_concurso` varchar(50) DEFAULT NULL,
  `fecha_baja` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `motivo_baja` varchar(50) DEFAULT NULL,
  `nombre_apellido` varchar(100) DEFAULT NULL,
  `puesto_baja` varchar(100) DEFAULT NULL,
  `especialidad_baja` varchar(100) DEFAULT NULL,
  `unificador_puestos` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id_baja`,`periodo`),
  KEY `fk_bajas_cargo` (`id_cargo`,`periodo`),
  KEY `IDX_b80d7da2d1cb2f050d81af0b2d` (`id_cargo`),
  KEY `IDX_83488853987f5a3cd2bbc2649a` (`periodo`),
  KEY `IDX_f02eb396806a6b9cbb1f364b3e` (`id_baja`,`periodo`),
  CONSTRAINT `FK_a49a0eb07b0b8fdb7c079c53e67` FOREIGN KEY (`id_cargo`, `periodo`) REFERENCES `cargos` (`id_cargo`, `periodo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
