DROP TABLE IF EXISTS `bajas_consolidadas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bajas_consolidadas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `usuario` varchar(100) DEFAULT NULL,
  `cuil` varchar(20) DEFAULT NULL,
  `nombre_apellido` varchar(200) DEFAULT NULL,
  `sigla` varchar(20) DEFAULT NULL,
  `efector` varchar(200) DEFAULT NULL,
  `codigo_cargo` varchar(50) DEFAULT NULL,
  `puesto_baja` varchar(150) DEFAULT NULL,
  `especialidad_baja` varchar(150) DEFAULT NULL,
  `partida_presupuestaria` varchar(50) DEFAULT NULL,
  `escalafon` varchar(50) DEFAULT NULL,
  `pou_pof` varchar(10) DEFAULT NULL,
  `unificador_puestos` varchar(100) DEFAULT NULL,
  `codigo_registro` int DEFAULT NULL,
  `ex_baja` varchar(150) DEFAULT NULL,
  `fecha_baja` varchar(15) DEFAULT NULL,
  `carga_horaria` varchar(20) DEFAULT NULL,
  `motivo_baja` varchar(150) DEFAULT NULL,
  `dgalh_validacion` varchar(5) DEFAULT NULL,
  `if_dgalh` varchar(150) DEFAULT NULL,
  `doc_respaldatoria` varchar(150) DEFAULT NULL,
  `fecha_pase_paralelo` varchar(15) DEFAULT NULL,
  `genera_concurso` varchar(5) DEFAULT NULL,
  `es_cph` tinyint(1) NOT NULL DEFAULT '0',
  `ccoo_especialidad` varchar(150) DEFAULT NULL,
  `tipo_efector` varchar(100) DEFAULT NULL,
  `cargo_baja` varchar(200) DEFAULT NULL,
  `origen` varchar(50) DEFAULT NULL,
  `obra` tinyint(1) DEFAULT '0',
  `expediente_concurso` varchar(150) DEFAULT NULL,
  `fecha_generacion` varchar(15) DEFAULT NULL,
  `fecha_caratulacion` varchar(15) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`),
  KEY `idx_bajas_consolidadas_genera_concurso` (`genera_concurso`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
