INSERT INTO `minutas` VALUES (3,'HGARM','-','{\"rows\": [{\"col_1\": \"Acelerar la designación anestesióloga planta\", \"col_1775483196753\": \"1\", \"col_1775483223809\": \"FINALIZADA\", \"col_1776709866800\": \"RESOL-2025-2937-GCABA-MSGC - Chiesa Paula designada 22/07\"}, {\"col_1\": \"Reconvertir 2 cargos vacantes PLANTA de anestesiología a 2 cargos de hematología con orientación a transplante de médula. \", \"col_1775483196753\": \"2\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"\\\"1 FINALIZADO. DESIGNADA: FERNANDEZ MELISA ROMINA - Activa en SIAL 06/01/26\\n1 ABRE INSCRIPCIONES EL 18/05/2026 HASTA EL 28/05/2026\\\"\"}, {\"col_1\": \"Reconvertir 7 cargos vacantes POU de clínica a 7 de hemodinamia POU (Cardiologos)\", \"col_1775483196753\": \"7\", \"col_1775483223809\": \"CUMPLIDO ETAPA 1 - EN PROCESO CONCURSOS\", \"col_1776709866800\": \"\\\"5 PROX A DESIGNAR: CON TAD: \\nMOGUILNER ALEJANDRO (PARA ITE)\\nQUIROGA MERCEDES (CON APTO MÉDICO)\\nCORCUERA ALVARADO LUIS (FECHA APTO MÉDICO 24/4)\\nDE CANDIDO LAURA (FINALIZADO - NO ACTIVA EN SIAL - ESPERA NOTIFICACIÓN DE RESOL)\\nCORTEZ YANEZ JORGE ORLANDO (CON ITE PARA HACER EL PROYECTO DE RESO) \\n\\n2 DESIERTOS\\\"\"}, {\"col_1\": \"Reconvertir 3 vacantes de Anestesiología a 1 DxI (Ecografía), 1 Clinico y 1 Psiquiatra\", \"col_1775483196753\": \"3\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"\\\"DXI CERRÓ INSCRIPCIONES 16/4 (UNA POSTULANTE)  \\nMÉDICO CLÍNICO PARA SUBIR OM, SE TOMÓ EXAMEN 17/4 (1 POSTULANTE - ZUNIGA CACERES SALVADOR EDGARDO)\\nPSIQUIATRA CERRÓ INSCRIPCIONES 16/4 - 2 POSTULANTES \\\"\"}, {\"col_1\": \"Reconvertir dos cargos de planta (pediatria y alergia) en anestesia planta, Tienen residentes terminando que se quieren quedar en el Hospi\", \"col_1775483196753\": \"2\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"\\\"1 Autorizando:  para sorteo de jurado (EX-2026-04871284- -GCABA-DGAYDRH)\\n1 Aguardando la baja\\\"\"}, {\"col_1\": \"3 Cargos Incrementales de Odontólogo de Planta\", \"col_1775483196753\": \"3\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"\\\"CONCURSOS CENTRALIZADOS: SE TOMÓ EXAMEN EL 7/4 - ADJUDICADOS (CON TAD): Lemlich Lautaro\\nQuintana Laura\\nIbañez Sol Belen\\\"\"}, {\"col_1\": \"1 Cargo Incremental de Oftalmologo de Planta\", \"col_1775483196753\": \"1\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"INSCRIPCIONES DESDE 07/04/2026 HASTA EL 22/04/2026 - 17 INSCRIPTOS HASTA EL DÍA DE LA FECHA \"}, {\"col_1\": \"1 Cargo Incremental de Oftalmo Pediatria de Planta\", \"col_1775483196753\": \"1\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"INSCRIPCIONES DESDE 07/04/2026 HASTA EL 22/04/2026 - 4 INSCRIPTOS HASTA EL DÍA DE LA FECHA \"}, {\"col_1\": \"1 Cargo Incremental de Fonoaudiología\", \"col_1775483196753\": \"1\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"PARA SORTEO DE JURADO \"}, {\"col_1\": \"1 Cargo Incremental de Endocrinología\", \"col_1775483196753\": \"1\", \"col_1775483223809\": \"EN PROCESO\", \"col_1776709866800\": \"PARA SORTEO DE JURADO \"}], \"columns\": [{\"id\": \"col_1\", \"name\": \"DETALLE\", \"type\": \"date\"}, {\"id\": \"col_1775483196753\", \"name\": \"Q EQUIPOS TOTAL\", \"type\": \"text\"}, {\"id\": \"col_1775483223809\", \"name\": \"ESTADO\", \"type\": \"number\"}, {\"id\": \"col_1776709866800\", \"name\": \"OBSERVACIONES\", \"type\": \"text\"}]}',6,'2026-04-06 13:47:33','2026-04-20 18:34:32'),(16,'HGAPP','-','{\"rows\": [{\"col_1\": \"Transferir 1 cargo de farmacia COPS de SSAPAC al hospital \", \"col_1776716582412\": \"Reconversión de cargos\", \"col_1776716582820\": \"1\", \"col_1776716583172\": \"FINALIZADA\", \"col_1776716626226\": \"\\\"Transferencia VIEGAS PATRICIA ISABEL (CPH -FARMACEUTICA DE PLANTA)        \\nde SSAPAC a HGAPP por RESOL-2025-3806-GCABA-MSGC\\nTransferencia SUAREZ MARCELA SUSANA (TEC. FARMACIA)\\nde SSAPAC a HGAPP por RESOL-2025-2983-GCABA-SSGRH\\\"\"}, {\"col_1\": \"Reconvertir 2 cargos POF a fonoaudiología a medida que tengan bajas menos prioritarias\", \"col_1776716582412\": \"Reconversión de cargos\", \"col_1776716582820\": \"2\", \"col_1776716583172\": \"PENDIENTE\", \"col_1776716626226\": \"A la espera de Bajas pasibles de reconversion - Actualmente no cuenta con bajas\"}, {\"col_1\": \"Cambio de 3 enfermeras a 2 técnicos extraccionistas y 1 técnico de farmacia.\", \"col_1776716582412\": \"RRHH Incremental\", \"col_1776716582820\": \"3\", \"col_1776716583172\": \"FINALIZADA\", \"col_1776716626226\": \"\\\"TEC LABORATORIO:  DESIGNADO: \\nMaria Fernanda Cevilan  - LOZA CRISTIAN DAVID\\nTEC FARMACIA: DESIGNADO :\\nLUNA, CANDELA\\\"\"}, {\"col_1\": \"Reconvertir 1cargo POU profes guardia sin especialidad en 7 cargos POF: 1 oftalmo pediatrico, 1 Clinica medica (turno vespertino), 1 DxI ecografia, 1 odonto adultos, 1 cardio para ecocardio,  1 psiquiatra infanto juvenil y 1 fonoaudiologo\", \"col_1776716582412\": \"Reconversión de cargos\", \"col_1776716582820\": \"7\", \"col_1776716583172\": \"CUMPLIDO ETAPA 1 - EN PROCESO CONCURSOS\", \"col_1776716626226\": \"\\\"Estado concursos: \\nOFTALMOLOGIA - DESIGNADO - RAMELLO MARIA PIERINA - ALTA EN SIAL 25/03\\nCLINICA MEDICA - EN NUEVA INSCRIPCION - EXAMEN 22/4 - 2 INSCRIPTOS\\nDIAGNOSTICO POR IMAGENES (ECOGRAFIA) DESIGNADO - MANNOCCI DIEGO MARTIN - ALTA EN SIAL 06/03\\nODONTOLOGIA GENERAL  DESIGNADO- TRAPANI FRETES IRIS GLORIA, ALTA 5/3/2026\\nPSIQUIATRIA INFANTO JUVENIL DESIGNADO - GALARZA CAIZA SANTIAGO PAULO - ACTIVO DESDE EL 02/02\\nFONOAUDIOLOGIA DESIGNADO - CORVALAN JULIETA SOL - ACTIVO 10/2/2026\\nCARDIOLOGIA DESINGADO - LEGUIZA CLAUDIA INES - ACTIVO DESDE EL 02/02\\\"\"}, {\"col_1\": \"5 cargos incrementales de Odontología de planta\", \"col_1776716582412\": \"RRHH Incremental\", \"col_1776716582820\": \"5\", \"col_1776716583172\": \"EN PROCESO\", \"col_1776716626226\": \"Concurso centralizado: Adjudicacion martes 14/04\"}, {\"col_1\": \"1 cargo incremental 1 