  `sigla_efector` varchar(20) DEFAULT NULL,
  `tipo_efector` varchar(100) DEFAULT NULL,
  `escalafon_baja` varchar(50) DEFAULT NULL,
  `origen` varchar(200) DEFAULT NULL,
  `conjuntos` varchar(200) DEFAULT NULL,
  `estado` varchar(50) DEFAULT NULL,
  `sub_estado` varchar(100) DEFAULT NULL,
  `sub_estado_3` varchar(100) DEFAULT NULL,
  `cambio_especialidad` varchar(5) DEFAULT NULL,
  `tipo_baja` varchar(50) DEFAULT NULL,
  `cargo` varchar(50) DEFAULT NULL,
  `ee_baja` varchar(150) DEFAULT NULL,
  `cuil_baja` varchar(20) DEFAULT NULL,
  `nombre_baja` varchar(200) DEFAULT NULL,
  `fecha_baja` varchar(15) DEFAULT NULL,
  `escalafon_1` varchar(50) DEFAULT NULL,
  `puesto_1` varchar(150) DEFAULT NULL,
  `especialidad_baja` varchar(150) DEFAULT NULL,
  `carga_horaria` varchar(20) DEFAULT NULL,
  `motivo_baja` varchar(150) DEFAULT NULL,
  `doc_respaldatoria` varchar(150) DEFAULT NULL,
  `fecha_pase_paralelo` varchar(15) DEFAULT NULL,
  `partida_presupuestaria` varchar(50) DEFAULT NULL,
  `unificador_puestos` varchar(100) DEFAULT NULL,
  `ee_concurso` varchar(150) DEFAULT NULL,
  `fecha_ee_concurso` varchar(15) DEFAULT NULL,
  `escalafon_2` varchar(50) DEFAULT NULL,
  `puesto_2` varchar(150) DEFAULT NULL,
  `especialidad_solicitada` varchar(150) DEFAULT NULL,
  `fecha_autorizacion` varchar(15) DEFAULT NULL,
  `sorteo_jurado` tinyint(1) DEFAULT NULL,
  `disposicion` varchar(100) DEFAULT NULL,
  `fecha_insc_desde` varchar(15) DEFAULT NULL,
  `fecha_insc_hasta` varchar(15) DEFAULT NULL,
  `q_inscriptos` int DEFAULT NULL,
  `examen_publicado` tinyint(1) DEFAULT NULL,
  `fecha_examen` varchar(15) DEFAULT NULL,
  `orden_merito` tinyint(1) DEFAULT NULL,
  `fecha_orden_merito` varchar(15) DEFAULT NULL,
  `fecha_ifacs` varchar(15) DEFAULT NULL,
  `insal` tinyint(1) DEFAULT NULL,
  `fecha_insal` varchar(15) DEFAULT NULL,
  `ee_designacion` varchar(150) DEFAULT NULL,
  `fecha_ee_designacion` varchar(15) DEFAULT NULL,
  `nombre_designacion` varchar(200) DEFAULT NULL,
  `cuil_designacion` varchar(20) DEFAULT NULL,
  `carga_documentacion` tinyint(1) DEFAULT NULL,
  `fecha_apto_medico` varchar(15) DEFAULT NULL,
  `fecha_ite` varchar(15) DEFAULT NULL,
  `reso_a_la_firma` tinyint(1) DEFAULT NULL,
  `resolucion_designacion` varchar(100) DEFAULT NULL,
  `fecha_resolucion` varchar(15) DEFAULT NULL,
  `fecha_cargo` varchar(15) DEFAULT NULL,
  `cargo_sial` varchar(50) DEFAULT NULL,
  `suspendido` tinyint(1) DEFAULT NULL,
  `dispo_desierta` varchar(50) DEFAULT NULL,
  `fecha_dispo_desierta` varchar(15) DEFAULT NULL,
  `observaciones` varchar(1000) DEFAULT NULL,
  `cargo_baja` varchar(200) DEFAULT NULL,
  `if_solicitante` varchar(150) DEFAULT NULL,
  `proyecto_resolucion` tinyint(1) DEFAULT NULL,
  `obra` tinyint(1) DEFAULT '0',
  `doc_cambio_especialidad` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`),
  KEY `fk_seguimiento_cph_baja` (`id_baja`),
  KEY `idx_seguimiento_cph_sigla_estado` (`sigla_efector`,`estado`),
  KEY `idx_seguimiento_cph_ee_concurso` (`ee_concurso`),
  KEY `idx_seguimiento_cph_ee_baja` (`ee_baja`),
  KEY `idx_seguimiento_cph_nombre_baja` (`nombre_baja`),
  CONSTRAINT `fk_seguimiento_cph_baja` FOREIGN KEY (`id_baja`) REFERENCES `bajas_consolidadas` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
